package org.circus.core;
import java.io.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
/**155 actual validator/helper programs, controlled native C-locale leaves.*/
public final class Pc1InstallKeyTests {
 private static int checks;
 private static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 private static int number(Object v){return ((Number)v).intValue();}
 private static byte[] unhex(String s){byte[] b=new byte[s.length()/2];for(int n=0;n<b.length;n++)b[n]=(byte)Integer.parseInt(s.substring(n*2,n*2+2),16);return b;}
 private static Pc1NativeMemory memory(){return new Pc1NativeMemory(Pc1NativeFrame.zeroBss(),Pc1CodeBuffer.zeroBss(),new Pc1NativeMemory.SettingsBytes(){public int read(int at)throws IOException{throw new IOException("unexpected settings read");}public void write(int at,int value)throws IOException{throw new IOException("unexpected settings write");}});}
 private static void bytes(Pc1NativeMemory m,int base,byte[] raw)throws IOException{m.bind(base,raw.length,new Pc1NativeMemory.Region(){public int read(int at){return raw[at]&255;}public void write(int at,int value){raw[at]=(byte)value;}});}
 private static final String FIXTURE=new StringBuilder().append("").append("").append("").append("").append("").append("").toString();
 public static int run()throws Exception{
  checks=0;Map<?,?> root=(Map<?,?>)DataJson.parse(new String(Base64.getDecoder().decode(FIXTURE),StandardCharsets.UTF_8));List<?> vectors=(List<?>)root.get("vectors");check(vectors.size()==155,"all original validator programs embedded");
  for(Object object:vectors){Map<?,?> row=(Map<?,?>)object;Pc1NativeMemory bus=memory();byte[] original=unhex((String)row.get("raw")),raw=Arrays.copyOf(original,original.length+1),table=new byte[44];List<?> words=(List<?>)row.get("table");for(int n=0;n<11;n++)for(int k=0;k<4;k++)table[n*4+k]=(byte)(number(words.get(n))>>>(k*8));bytes(bus,0xe90000,raw);bytes(bus,0x43da78,table);List<String> trace=new ArrayList<>();int[] calls={0};
   Pc1InstallKey validator=new Pc1InstallKey(bus,new Pc1InstallKey.Locale(){public int upper42097E(int value){trace.add("u:"+value);if(++calls[0]==1&&row.containsKey("mutation")){List<?> mutation=(List<?>)row.get("mutation");raw[number(mutation.get(0))]=(byte)number(mutation.get(1));}return value>=97&&value<=122?value-32:value;}public int digit420AD0(int value){trace.add("d:"+value);return value>=48&&value<=57?4:0;}});
   check(validator.validate(0xe90000,number(row.get("flags")))==number(row.get("result")),"complete validator matches original signed return");check(trace.equals(row.get("trace")),"signed-byte CRT calls preserve exact original order");check(Arrays.equals(raw,unhex((String)row.get("source"))),"original source re-reads observe CRT callback mutation");validator.requireBoundary();
  }
  Pc1InstallKey.Locale forbidden=new Pc1InstallKey.Locale(){public int upper42097E(int v)throws IOException{throw new IOException("unexpected CRT call");}public int digit420AD0(int v)throws IOException{throw new IOException("unexpected CRT call");}};check(new Pc1InstallKey(memory(),forbidden).validate(0,0)==-5,"bad flags return before any source or CRT access");
  Pc1NativeMemory unknown=memory();byte[] unterminated=new byte[12];Arrays.fill(unterminated,(byte)'A');bytes(unknown,0xe90000,unterminated);boolean gated=false;try{new Pc1InstallKey(unknown,forbidden).validate(0xe90000,32);}catch(IOException expected){gated=true;}check(gated,"strlen consumes full source before length comparison and never invents an unknown NUL");
  Pc1NativeMemory stack=memory();bytes(stack,0xe90000,new byte[]{'A','A','A','A','A','A','A','A','A','A','A',0});byte[] perm=new byte[44];perm[0]=12;bytes(stack,0x43da78,perm);Pc1InstallKey key=new Pc1InstallKey(stack,new Pc1InstallKey.Locale(){public int upper42097E(int v){return v;}public int digit420AD0(int v){return 0;}});gated=false;try{key.validate(0xe90000,32);}catch(IOException expected){gated=expected.getMessage().contains("unknown native local");}check(gated,"mutable permutation cannot turn an uninitialized local suffix into zero");key.requireBoundary();
  Pc1NativeMemory large=memory();final int length=1048587;int[] last={-1};large.bind(0xe90000,length+1,new Pc1NativeMemory.Region(){public int read(int at){last[0]=at;return at==length?0:'A';}public void write(int at,int value)throws IOException{throw new IOException("fixture readonly source");}});check(new Pc1InstallKey(large,forbidden).validate(0xe90000,32)==-4&&last[0]==length,"native REPNE strlen consumes a wholly known source past one MiB before rejecting length");return checks;
 }
 public static void main(String[] args)throws Exception{System.out.println("PASS "+run()+" install-key validation checks");}
}
